def write(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2)+'\n')

def main():
    path = ROOT/'library/styles/catalog.json'
    previous = {r['id']:r for r in json.loads(path.read_text())['records']} if path.exists() else {}
    categories, records = [], []
    for cat, zh, en, uses_zh, uses_en, lines in GROUPS:
        categories.append(dict(id='style_'+cat, name_zh=zh, name_en=en))
        for line in lines.strip().splitlines():
            slug, namezh, nameen, promptzh, prompten, distinctzh, distincten = [v.strip() for v in line.split('|')]
            identifier = 'style_'+slug
            prompten = 'Visual style: '+prompten+'. Preserve the prescribed scene, walking action and camera path.'
            promptzh = '视觉风格：'+promptzh+'。保持既定场景、行走动作与相机路径。'
            record = dict(id=identifier, kind='style', category='style_'+cat, name_zh=namezh, name_en=nameen,
                aliases=[namezh,nameen]+(['荧光纸艺拼贴','Fluorescent Papercraft Collage'] if slug in ('fluorescent_cutout','neon_paper_sculpture') else []),
                prompt_zh=promptzh, prompt_en=prompten, example_prompt_zh=BASE_ZH+'\n\n'+promptzh,
                example_prompt_en=BASE_EN+'\n\n'+prompten,
                description_zh=promptzh.removeprefix('视觉风格：').split('；避免')[0].split('；保留')[0]+'。',
                description_en=prompten.removeprefix('Visual style: ').split('; avoid')[0].split('; retain')[0]+'.',
                use_cases_zh=uses_zh+'；以'+namezh+'的视觉语言呈现相同侧跟场景。',
                use_cases_en=uses_en+'; present the matched side-tracking scene through '+nameen+' visual language.',
                distinctions_zh=distinctzh+'。', distinctions_en=distincten+'.',
                status='pending', planned_frames=124, first_batch=slug in ('halftone_pop','risograph','arcade_low_poly','fluorescent_cutout','neon_paper_sculpture','bw_infrared'))
            if identifier in previous:
                old=previous[identifier]
                # Reviewed prompt adjustments and assets survive a catalog rebuild.
                record=old
            records.append(record)
    assert len(records)==74
    assert [sum(r['category']==c['id'] for r in records) for c in categories]==[12,12,14,14,12,10]
    write(path,dict(version=1,categories=categories,records=records))
    from generate_styles import workflow
    graph=workflow(dict(id='style_template',example_prompt_en=BASE_EN,planned_frames=124),202611040001)
    write(ROOT/'library/styles/profile.json',dict(version=1,seed=202611040001,base_prompt_en=BASE_EN,base_prompt_zh=BASE_ZH,
        base_prompt_sha256=hashlib.sha256(BASE_EN.encode()).hexdigest(),width=576,height=320,frames=124,fps=24,steps=16,sampler='er_sde',scheduler='simple',cfg=1,
        workflow_template=graph,encoding=dict(codec='h264',pixel_format='yuv420p',crf=18,preset='medium',audio=False),
        note='Same base prompt, seed, models and sampling; only the style suffix, output path and explanatory titles vary. AI visual simulations are not claims of physical production.'))
if __name__=='__main__': main()
